def sum_squares(lst):
    res = 0
    for i in range(len(lst)):
        if (i % 3 == 0) or ((i + 1) % 4 == 0):
            res += lst[i] * lst[i]
        else:
            res += lst[i] ** 2
    return (res)

import re
def words_in_sentence(sentence):
    patterns = '^[a-zA-Z]+ [a-zA-Z]+$'
    if not re.search(patterns, sentence):
        return ''
    words = re.findall(r"\w+", sentence)
    primes = [i for i in range(2, 100) if all(i % j != 0 for j in range(2, i))]
    result = [word for word in words if len(word) in primes]
    return ' '.join(result)

