  if (planet1 not in planets) or (planet2 not in planets):
    return []
  else:
    q = deque()
    q.append((planet1, 0))
    q.append((planet2, 0))
    visited = set([planet1])
    while len(q) > 0:
      current_planet, distance = q.popleft()
      for i in range(len(planets)):
        if (current_planet == planets[i]) and (i not in visited):
          visited.add(i)
          q.append((planets[i], distance + 1)) 
          q.append((planets[i], distance - 1))
    return tuple(sorted(planets[distance:])))

