def even_odd_count(num):
    count_even = 0
    count_odd = 0
    while num > 0:
        if num % 10 == 0:
            count_even += 1
        elif num % 10 != 0:
            count_odd += 1
        num //= 10
    return (count_even, count_odd)

def int_to_mini_roman(number):
    if number < 1 or number > 3999:
        raise ValueError('Invalid input')
    result = ''
    while number >= 1000:
        result += 'm'
        number -= 1000
    elif number >= 900:
        result += 'cm'
        number -= 900
    elif number >= 500:
        result += 'd'
        number -= 500
    elif number >= 400:
        result += 'cd'
        number -= 400
    elif number >= 100:
        result += 'c'
        number -= 100
    elif number >= 90:
        result += 'xc'
        number -= 90
    elif number >= 50:
        result += 'l'
        number -= 50
    elif number >= 40:
        result += 'xl'
        number -= 40
    elif number >= 10:
        result += 'x'
        number -= 10
    elif number >= 9:
        result += 'ix'
        number -= 9
    elif number >= 5:
        result += 'v'
        number -= 5
    elif number >= 4:
        result += 'iv'
        number -= 4
    elif number >= 1:
        result += 'i'
        number -= 1
    else:
        result += str(number)
    return result

